const $=s=>document.querySelector(s); const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
function normalizeCurrencyCode(value){const raw=String(value??'').trim(),code=raw.toUpperCase(),supported=['USD','NGN','IDR','THB','MYR','PHP','VND'];if(supported.includes(code))return code;return ({'美元':'USD','美金':'USD','奈拉':'NGN','印尼盾':'IDR','泰铢':'THB','林吉特':'MYR','马来西亚林吉特':'MYR','菲律宾比索':'PHP','越南盾':'VND'})[raw]||raw}
function priceMarkup(vehicle){const currency=normalizeCurrencyCode(vehicle.currency),amount=String(vehicle.price??'');return `${currency?`<span class="currency-code notranslate" translate="no" lang="en">${esc(currency)}</span> `:''}<span class="price-value notranslate" translate="no" lang="en">${esc(amount)}</span>`}
function safePhoto(value){const s=String(value||'');return /^https?:\/\//i.test(s)||/^\/uploads\/[\w.-]+$/.test(s)?s:''}
function vehicleImageList(v){const raw=[...(Array.isArray(v?.images)?v.images:[]),v?.image];return [...new Set(raw.map(safePhoto).filter(Boolean))]}
function validatePhotos(form){const state=form._photoManager;if(state&&!syncVehiclePhotoLink(form))return false;const files=state?state.items.filter(item=>item.kind==='upload').map(item=>item.file):Array.from(form.elements.photos?.files||[]),count=state?state.items.length:files.length;if(count>20||files.some(file=>file.size>12*1024*1024||!/^image\/(jpeg|png|webp|gif)$/.test(file.type))){const message='最多保留20张JPEG、PNG、WebP或GIF照片，每张不超过12MB。';if(state){state.message=message;renderVehiclePhotoManager(form)}else alert(message);return false}return true}
function vehicleGallery(v){const images=vehicleImageList(v),title=localized(v,'title'),prev=images.length>1?'<button type="button" class="gallery-nav gallery-prev" data-gallery-prev aria-label="Previous photo">&#8249;</button>':'',next=images.length>1?'<button type="button" class="gallery-nav gallery-next" data-gallery-next aria-label="Next photo">&#8250;</button>':'';if(!images.length)return '<div class="vehicle-gallery"><div class="gallery-stage gallery-empty" role="img" aria-label="No vehicle photo">No photo</div></div>';return `<div class="vehicle-gallery" data-gallery-index="0" data-gallery-count="${images.length}"><div class="gallery-stage">${prev}<img class="detail-img gallery-main" data-gallery-main src="${esc(images[0])}" alt="${esc(title)} - Photo 1">${next}</div><div class="photo-thumbs" role="list">${images.map((url,i)=>`<button type="button" class="photo-thumb" data-gallery-photo="${esc(url)}" data-gallery-index="${i}" data-gallery-alt="${esc(title)} - Photo ${i+1}" aria-label="Photo ${i+1}" aria-pressed="${i===0}"><img src="${esc(url)}" alt="Photo ${i+1}" loading="lazy"></button>`).join('')}</div></div>`}
function setGalleryIndex(gallery,index){const buttons=[...gallery.querySelectorAll('[data-gallery-photo]')],count=buttons.length;if(!count)return;const next=(index+count)%count,button=buttons[next],main=gallery.querySelector('[data-gallery-main]');if(!main)return;main.src=safePhoto(button.dataset.galleryPhoto);main.alt=button.dataset.galleryAlt||`Photo ${next+1}`;gallery.dataset.galleryIndex=String(next);buttons.forEach((item,i)=>item.setAttribute('aria-pressed',String(i===next)));button.scrollIntoView({behavior:'smooth',block:'nearest',inline:'nearest'})}
function stepGallery(gallery,direction){setGalleryIndex(gallery,Number(gallery.dataset.galleryIndex||0)+direction)}
document.addEventListener('click',e=>{const thumb=e.target.closest('[data-gallery-photo]'),control=e.target.closest('[data-gallery-prev],[data-gallery-next]'),target=thumb||control;if(!target)return;const gallery=target.closest('.vehicle-gallery');if(!gallery)return;if(thumb)setGalleryIndex(gallery,Number(thumb.dataset.galleryIndex||0));else stepGallery(gallery,control.hasAttribute('data-gallery-next')?1:-1)});
document.addEventListener('keydown',e=>{if(e.key!=='ArrowLeft'&&e.key!=='ArrowRight')return;const gallery=document.activeElement?.closest?.('.vehicle-gallery');if(!gallery)return;e.preventDefault();stepGallery(gallery,e.key==='ArrowRight'?1:-1)});
let galleryTouch=null;document.addEventListener('touchstart',e=>{const stage=e.target.closest?.('.gallery-stage');if(stage&&e.touches.length===1)galleryTouch={stage,x:e.touches[0].clientX,y:e.touches[0].clientY}}, {passive:true});document.addEventListener('touchend',e=>{if(!galleryTouch)return;const {stage,x,y}=galleryTouch;galleryTouch=null;const touch=e.changedTouches[0],dx=touch.clientX-x,dy=touch.clientY-y;if(Math.abs(dx)<40||Math.abs(dx)<=Math.abs(dy))return;const gallery=stage.closest('.vehicle-gallery');if(gallery)stepGallery(gallery,dx<0?1:-1)}, {passive:true});
