function applyLanguage(targetLanguage=language){const dictionary=targetLanguage==='zh'?translations:{...(vehicleAttributeLabels[targetLanguage]||{}),...(localeText[targetLanguage]||{})};if(!dictionary)return;const walker=document.createTreeWalker($('#app'),NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){const original=node.nodeValue.trim();if(dictionary[original])node.nodeValue=node.nodeValue.replace(original,dictionary[original]);}$('#app').querySelectorAll('[placeholder]').forEach(el=>{if(dictionary[el.placeholder])el.placeholder=dictionary[el.placeholder]});}
const baseCarsRenderer=cars;
const knownBrandAliases=Object.freeze({'mercedes benz':'mercedes-benz',mercedesbenz:'mercedes-benz','land rover':'land-rover',landrover:'land-rover'});
function brandKey(value){const key=String(value||'').trim().toLocaleLowerCase();return knownBrandAliases[key]||key}
const builtinBrandLogos=window.AUTOHAVEN_BRAND_LOGOS||{};
const builtinBrandNames=window.AUTOHAVEN_BRAND_NAMES||{};
function brandAliases(brand){return [brand.name,brand.name_zh,brand.slug,...(brand.aliases||[])].map(brandKey).filter(Boolean)}
function brandIdentityKeys(brand){return [brand.name,brand.slug,...(brand.aliases||[])].map(brandKey).filter(key=>/^[a-z0-9 -]+$/.test(key))}
function brandLogo(brand){return brand.logo||builtinBrandLogos[brand.slug]||''}
function buildBrandCatalog(catalog){
  const brands=Array.isArray(catalog)?catalog.filter(brand=>brand&&String(brand.name||'').trim()).map(brand=>{const builtIn=builtinBrandNames[brand.slug]||{};return{name:String(brand.name||builtIn.name||brand.slug).trim(),name_zh:String(brand.name_zh||builtIn.name_zh||brand.name||brand.slug).trim(),slug:String(brand.slug||brand.name).trim(),logo:/^https:\/\//i.test(String(brand.logo||''))?String(brand.logo):'',aliases:[builtIn.name,builtIn.name_zh].filter(Boolean)}}):[];
  for(const [slug,names] of Object.entries(builtinBrandNames)){
    const extra={name:names.name||slug,name_zh:names.name_zh||names.name||slug,slug,logo:builtinBrandLogos[slug]||'',aliases:[names.name,names.name_zh].filter(Boolean)};
    const isUsed=vehicles.some(vehicle=>[extra.name,extra.name_zh,extra.slug,...extra.aliases].some(alias=>brandKey(alias)===brandKey(vehicle.brand)));
    if(isUsed&&!brands.some(brand=>[brand.name,brand.name_zh,brand.slug,...brand.aliases].some(alias=>[extra.name,extra.name_zh,extra.slug,...extra.aliases].some(value=>brandKey(alias)===brandKey(value)))))brands.push(extra);
  }
  for(const name of [...new Set(vehicles.map(vehicle=>String(vehicle.brand||'').trim()).filter(Boolean))]){
    if(brands.some(brand=>[brand.name,brand.name_zh,brand.slug,...brand.aliases].some(alias=>brandKey(alias)===brandKey(name))))continue;
    const slug=name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||`custom-${brands.length+1}`;
    brands.push({name,name_zh:name,slug,logo:builtinBrandLogos[slug]||'',aliases:[]});
  }
  const unique=[];
  for(const brand of brands){
    const aliases=brandAliases(brand),identityKeys=brandIdentityKeys(brand),existing=unique.find(item=>brandIdentityKeys(item).some(key=>identityKeys.includes(key)));
    if(!existing){unique.push(brand);continue}
    existing.aliases=[...new Set([...brandAliases(existing),...aliases])];
    if(!existing.logo&&brand.logo)existing.logo=brand.logo;
  }
  return unique.sort((a,b)=>a.name.localeCompare(b.name));
}
function brandFilterSection(catalog){
  const brands=publicBrandCatalog=buildBrandCatalog(catalog);
  const countFor=brand=>vehicles.filter(vehicle=>brandMatches(vehicle.brand,brand.slug)).length;
  const labelFor=brand=>language==='zh'?brand.name_zh:brand.name;
  const markFor=brand=>brand.name.replace(/[^a-z0-9]/gi,'').slice(0,2).toUpperCase()||'BR';
  const iconFor=brand=>brandLogo(brand)?`<span class="brand-filter-icon brand-filter-icon-image"><img data-brand-logo src="${esc(brandLogo(brand))}" alt="" loading="lazy"><span class="brand-filter-initial">${esc(markFor(brand))}</span></span>`:`<span class="brand-filter-icon" aria-hidden="true">${esc(markFor(brand))}</span>`;
  const tile=(brand,count)=>`<button type="button" class="brand-filter-tile" data-brand-filter="${esc(brand.slug)}" aria-pressed="false">${iconFor(brand)}<span class="brand-filter-name">${esc(labelFor(brand))}</span><span class="brand-filter-count">${count}</span></button>`;
  const closeLabel=brandFilterCloseLabels[language]||brandFilterCloseLabels.en;
  const visibleBrands=brands.filter(brand=>countFor(brand)>0);
  return `<section class="brand-filter" id="brandFilterPanel" aria-hidden="true" hidden><button type="button" class="brand-filter-backdrop" data-brand-close aria-label="${esc(closeLabel)}"></button><div class="brand-filter-sheet" id="brandFilterSheet" role="dialog" aria-modal="true" aria-labelledby="brandFilterHeading"><div class="brand-filter-heading"><h2 id="brandFilterHeading">${esc(ft('brand'))}</h2><span>${visibleBrands.length}</span></div><div class="brand-filter-grid" role="group" aria-label="${esc(ft('brand'))}"><button type="button" class="brand-filter-tile is-active" data-brand-filter="" aria-pressed="true"><span class="brand-filter-icon brand-filter-icon-all" aria-hidden="true">✦</span><span class="brand-filter-name">${esc(ft('allBrands'))}</span><span class="brand-filter-count">${vehicles.length}</span></button>${visibleBrands.map(brand=>tile(brand,countFor(brand))).join('')}</div><div class="brand-filter-footer"><button type="button" class="brand-filter-close" data-brand-close aria-label="${esc(closeLabel)}">×</button></div></div></section><select id="brand" class="brand-filter-select" aria-hidden="true" tabindex="-1"><option value="">${esc(ft('allBrands'))}</option>${visibleBrands.map(brand=>`<option value="${esc(brand.slug)}">${esc(brand.name)}</option>`).join('')}</select>`;
}
cars=async function(){
  const html=await baseCarsRenderer();
  const catalog=await api('/api/brands').catch(()=>[]);
  const section=brandFilterSection(catalog);
  const withoutNativeBrand=html.replace(/<label><span>[^<]*<\/span><select id="brand">[\s\S]*?<\/select><\/label>/,`<label class="brand-filter-control"><button type="button" id="brandFilterToggle" aria-expanded="false" aria-controls="brandFilterPanel"><span id="brandFilterLabel">${esc(ft('allBrands'))}</span><span class="brand-filter-chevron" aria-hidden="true">⌄</span></button></label>`);
  const filterMarker='</div><div class="secondary-filters">';
  return withoutNativeBrand.includes(filterMarker)?withoutNativeBrand.replace(filterMarker,`</div>${section}<div class="secondary-filters">`):withoutNativeBrand.replace('</main>',`${section}</main>`);
};
function initBrandFilter(){
  addPhevFuelOption($('#fuelType'));
  const select=$('#brand');
  const trigger=$('#brandFilterToggle'),panel=$('#brandFilterPanel');
  if(!select||!trigger||!panel)return;
  const buttons=[...document.querySelectorAll('[data-brand-filter]')];
  const sync=()=>buttons.forEach(tile=>{
    const active=tile.dataset.brandFilter===select.value;
    tile.classList.toggle('is-active',active);
    tile.setAttribute('aria-pressed',String(active));
  });
  const updateLabel=()=>{const brand=publicBrandCatalog.find(item=>item.slug===select.value);$('#brandFilterLabel').textContent=brand?(language==='zh'?brand.name_zh:brand.name):ft('allBrands')};
  const close=()=>{panel.hidden=true;panel.setAttribute('aria-hidden','true');trigger.setAttribute('aria-expanded','false');document.body.classList.remove('brand-filter-open');trigger.focus({preventScroll:true})};
  const open=()=>{const filters=$('.mobile-filter-bar');if(filters)panel.style.setProperty('--brand-filter-top',`${Math.max(0,filters.getBoundingClientRect().bottom)}px`);panel.hidden=false;panel.setAttribute('aria-hidden','false');trigger.setAttribute('aria-expanded','true');document.body.classList.add('brand-filter-open');panel.querySelector('.brand-filter-close')?.focus({preventScroll:true})};
  trigger.onclick=()=>panel.hidden?open():close();
  panel.querySelectorAll('[data-brand-close]').forEach(button=>button.onclick=close);
  panel.onkeydown=event=>{if(event.key==='Escape'){close();trigger.focus({preventScroll:true})}};
  buttons.forEach(button=>button.onclick=()=>{select.value=button.dataset.brandFilter||'';sync();updateLabel();filterCars();close();trigger.focus({preventScroll:true})});
  sync();updateLabel();
}
document.addEventListener('error',event=>{
  const image=event.target.closest?.('[data-brand-logo]');
  if(!image)return;
  image.hidden=true;
  image.parentElement?.classList.add('has-fallback');
},true);
