function layout(content,active='Home'){const phone=String(salesPhone()).trim(),tel=phone.replace(/[^\d+(). -]/g,'');return `<header class="top shell"><a class="brand" href="#/">AUTO<span>HAVEN</span></a><nav class="nav"><a class="${active==='Home'?'active':''}" href="#/">Home</a><a class="${active==='Buy Cars'?'active':''}" href="#/cars">Buy Cars</a><a href="#/sell">Sell Your Car</a><a class="${active==='About'?'active':''}" href="#/about">About</a><select id="languageSwitch" aria-label="Language" style="width:auto;padding:8px;border:1px solid #e8ebef;border-radius:6px;background:#fff">${Object.entries(localeNames).map(([code,name])=>`<option value="${code}" ${language===code?'selected':''}>${name}</option>`).join('')}</select></nav>${phone?`<a class="phone" href="tel:${esc(tel)}">${esc(activeSales?.name||'')} ${esc(phone)}</a>`:''}</header>${content}<footer class="footer"><div class="shell">© 2026 AutoHaven Motors · Quality cars, transparent service.</div></footer>`}
function card(v){return cardLocalized(v)}
async function home(){vehicles=await api('/api/vehicles');const s=siteSettings;const wa=whatsappNumber(salesWhatsApp()||'12025550188');return layout(`<main><section class="hero"><div class="shell"><div class="eyebrow">Your next car starts here</div><h1>Drive away with confidence.</h1><p>Carefully selected pre-owned vehicles, honest prices and a team that makes buying your next car simple.</p><div class="actions"><a class="btn primary" href="#/cars">Browse vehicles</a><a class="btn" href="#/about">Meet our team</a></div></div><div class="hero-art"></div></section><section class="section shell"><div class="section-head"><div><div class="eyebrow">Featured inventory</div><h2>Find your next drive</h2></div><a class="btn" href="#/cars">View all cars</a></div><div class="grid">${vehicles.slice(0,3).map(card).join('')}</div></section><section class="contact-band"><div class="shell"><div class="eyebrow">Talk to a specialist</div><h2>Have a question about a vehicle?</h2><p class="muted">Our team is ready to help with pricing, availability and test drives.</p><div class="actions"><a class="btn primary" href="https://wa.me/${esc(wa)}">WhatsApp us</a><a class="btn" style="color:#fff;border-color:#52606c" href="tel:${esc(salesPhone())}">Call ${esc(salesPhone())}</a></div></div></section></main>`)}
async function cars(){vehicles=await api('/api/vehicles');const brands=[...new Set(vehicles.map(v=>v.brand).filter(Boolean))].sort(),bodies=[['Sedan','Sedan'],['Hatchback','Hatchback'],['SUV','SUV'],['Crossover','Crossover'],['MPV / Minivan','MPV / Minivan'],['Pickup Truck','Pickup Truck'],['Van','Van'],['Truck','Truck'],['Electric Vehicle','Electric Vehicle']],years=vehicleFilterYears();return layout(`<main class="page shell inventory-page"><div class="inventory-search"><strong><span id="carCount">${vehicles.length}</span> ${esc(ft('count'))}</strong><input id="q" placeholder="${esc(ft('search'))}"></div><div class="mobile-filter-bar"><label><span>${esc(ft('sort'))}</span><select id="sort"><option value="newest">${esc(ft('newest'))}</option><option value="price-low">${esc(ft('priceLow'))}</option><option value="price-high">${esc(ft('priceHigh'))}</option><option value="year-new">${esc(ft('yearNew'))}</option><option value="mileage-low">${esc(ft('mileageLow'))}</option></select></label><label><span>${esc(ft('brand'))}</span><select id="brand"><option value="">${esc(ft('allBrands'))}</option>${brands.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select></label><label><span>${esc(ft('price'))}</span><select id="priceRange"><option value="">${esc(ft('allPrices'))}</option><option value="0-10000">${esc(ft('under10'))}</option><option value="10000-20000">${esc(ft('from10to20'))}</option><option value="20000-30000">${esc(ft('from20to30'))}</option><option value="30000-">${esc(ft('over30'))}</option></select></label><label><span>${esc(ft('body'))}</span><select id="bodyType"><option value="">${esc(ft('allBodies'))}</option>${bodies.map(x=>`<option value="${x[0]}">${esc(vehicleTerm(x[1]))}</option>`).join('')}</select></label></div><div class="secondary-filters"><select id="fuelType"><option value="">${esc(ft('allFuels'))}</option><option value="Petrol">${esc(vehicleTerm("Petrol"))}</option><option value="Diesel">${esc(vehicleTerm("Diesel"))}</option><option value="Hybrid">${esc(vehicleTerm("Hybrid"))}</option><option value="Electric">${esc(vehicleTerm("Electric"))}</option></select><select id="status"><option value="">${esc(ft('allStatus'))}</option><option value="Available">${esc(ft('available'))}</option><option value="Reserved">${esc(ft('reserved'))}</option><option value="Sold">${esc(ft('sold'))}</option></select><select id="yearFilter" aria-label="${esc(ft('year'))}"><option value="">${esc(ft('allYears'))}</option>${years.map(year=>`<option value="${esc(year)}">${esc(year)}</option>`).join('')}</select></div><div id="cargrid" class="grid inventory-grid">${vehicles.map(card).join('')}</div></main>`,'Buy Cars')}function about(){return layout(`<main class="page shell"><div class="eyebrow">About AutoHaven</div><h1>A better way to buy a used car.</h1><p class="muted" style="max-width:650px;line-height:1.8">We believe car buying should feel straightforward. Every vehicle is presented honestly, with clear information and a real person ready to answer your questions.</p><section class="section"><div class="grid"><div><div class="eyebrow">01</div><h2>Curated inventory</h2><p class="muted">We select reliable cars with transparent history and realistic pricing.</p></div><div><div class="eyebrow">02</div><h2>Human service</h2><p class="muted">Talk directly with a specialist who knows each vehicle.</p></div><div><div class="eyebrow">03</div><h2>Easy next step</h2><p class="muted">Call, message or book a viewing whenever it suits you.</p></div></div></section></main>`,'About')}
function sell(){return layout(`<main class="page shell"><div class="eyebrow">Sell your car</div><h1>Thinking of selling?</h1><p class="muted">Send us a few details and our team will get back to you with an honest valuation.</p><div class="admin-panel" style="max-width:650px;margin-top:24px"><form class="form" id="sellForm"><input name="name" required maxlength="100" placeholder="Your name"><input name="phone" required maxlength="40" placeholder="Phone or WhatsApp"><input name="vehicle" maxlength="100" placeholder="Vehicle make and model"><input name="yearMileage" maxlength="100" placeholder="Year and mileage"><textarea name="message" class="full" rows="5" maxlength="1000" placeholder="Tell us about your car"></textarea><button class="btn primary" type="submit">Request a valuation</button><p id="sellResult" class="muted"></p></form></div></main>`)}
async function detailOld(id){const v=await api('/api/vehicles/'+id),whatsapp=whatsappNumber(salesWhatsApp()||v.whatsapp||v.phone||'12025550188');return layout(`<main class="page shell"><a class="muted" href="#/cars">← Back to inventory</a><div class="detail" style="margin-top:22px"><div class="detail-img" style="background-image:url('${esc(v.image)}')"></div><div><div class="eyebrow">${esc(v.status)}</div><h1>${esc(v.title)}</h1><div class="price" style="font-size:28px">${esc(v.price)}</div><div class="specs"><div class="spec"><small>Year</small>${esc(v.year)}</div><div class="spec"><small>Mileage</small>${esc(v.mileage)}</div><div class="spec"><small>Transmission</small>${esc(v.transmission)}</div><div class="spec"><small>Fuel</small>${esc(v.fuel)}</div><div class="spec"><small>Location</small>${esc(v.location)}</div><div class="spec"><small>Brand</small>${esc(v.brand)}</div></div><p class="muted" style="line-height:1.7">${esc(v.description)}</p><div class="actions"><a class="btn primary" href="https://wa.me/${whatsapp}">WhatsApp sales</a><a class="btn" href="tel:${esc(salesPhone()||v.phone||'12025550188')}">Call us</a></div></div></div></main>`)}
let currentAdmin=null,administratorAccounts=[];
async function admin(){
  const session=await api('/api/admin/session');
  currentAdmin=session.authenticated?session.admin:null;
  if(!currentAdmin)return `<div class="admin admin-login"><header class="admin-top"><a class="brand" href="#/">AUTO<span>HAVEN</span></a></header><main class="admin-login-main"><div class="admin-login-box"><div class="eyebrow">管理员登录</div><h1>登录后台</h1><p class="muted">使用管理员账号和密码登录内容管理系统</p><form id="loginForm" class="form admin-account-form"><label>管理员账号<input name="username" required minlength="3" maxlength="32" autocomplete="username" autocapitalize="none" spellcheck="false" placeholder="请输入管理员账号"></label><label>登录密码<input type="password" name="password" required maxlength="128" autocomplete="current-password" placeholder="请输入登录密码"></label><button class="btn primary" type="submit">登录</button><p id="loginError" class="form-feedback" role="alert"></p></form></div></main></div>`;
  vehicles=await api('/api/vehicles');contacts=await api('/api/contacts');salesLinks=await api('/api/sales-links');brands=await api('/api/brands');
  return `<div class="admin"><header class="admin-top"><a class="brand" href="#/">AUTO<span>HAVEN</span><small> 内容管理系统</small></a><div class="admin-top-actions"><span class="admin-user" id="currentAdminLabel">${esc(currentAdmin.name)}（${esc(currentAdmin.username)}）</span><button id="logout" class="top-link">退出登录</button></div></header><div class="admin-layout"><aside class="admin-sidebar"><div class="sidebar-caption">内容管理</div><button class="side-tab active" data-tab="dashboard"><span>⌂</span> 控制台</button><button class="side-tab" data-tab="vehicles"><span>▣</span> 车辆管理 <b>${vehicles.length}</b></button><button class="side-tab" data-tab="brands"><span>◈</span> 车辆品牌 <b>${brands.length}</b></button><button class="side-tab" data-tab="inquiries"><span>✉</span> 卖车咨询</button><div class="sidebar-caption">系统设置</div><button class="side-tab" data-tab="salesLinks"><span>↗</span> 销售链接</button>${currentAdmin.role==='superadmin'?'<button class="side-tab" data-tab="accounts"><span>♙</span> 管理员管理</button>':''}<button class="side-tab" data-tab="password"><span>▤</span> 修改密码</button></aside><main class="admin-content"><div class="admin-breadcrumb">控制台 <span>/</span> <strong id="adminTitle">概览</strong></div><div id="adminPanel" class="admin-panel"></div></main></div></div>`;
}
function dashboardPanel(){const available=vehicles.filter(v=>v.status==='Available').length,sold=vehicles.filter(v=>v.status==='Sold').length;return `<div class="dashboard-head"><div><div class="eyebrow">Dashboard</div><h1>管理概览</h1><p class="muted">欢迎回来，以下是当前网站内容状态。</p></div><a class="btn primary" href="#/" target="_blank">打开前台</a></div><div class="stat-grid"><div class="stat-card"><span class="stat-icon orange">▣</span><div><small>车辆总数</small><strong>${vehicles.length}</strong><em>全部车辆</em></div></div><div class="stat-card"><span class="stat-icon green">✓</span><div><small>在售车辆</small><strong>${available}</strong><em>当前可展示</em></div></div><div class="stat-card"><span class="stat-icon blue">♙</span><div><small>销售联系人</small><strong>${contacts.length}</strong><em>已配置人员</em></div></div><div class="stat-card"><span class="stat-icon purple">▤</span><div><small>已售车辆</small><strong>${sold}</strong><em>历史记录</em></div></div></div><div class="quick-panel"><h2>快捷操作</h2><div class="quick-actions"><button class="btn primary" data-tab="vehicles" data-quick-add="vehicle">+ 添加车辆</button><button class="btn" data-tab="contacts" data-quick-add="contact">+ 添加销售联系人</button><button class="btn" data-tab="inquiries">查看卖车咨询</button></div></div>`}
function adminAccountsPanel(){const rows=administratorAccounts.map(x=>`<tr><td><strong>${esc(x.name)}</strong><small class="table-subtitle">${esc(x.username)}</small></td><td>${x.role==='superadmin'?'超级管理员':'管理员'}</td><td><span class="status ${x.enabled?'status-available':'status-sold'}">${x.enabled?'正常':'已停用'}</span></td><td>${x.updatedAt?esc(new Date(x.updatedAt).toLocaleDateString('zh-CN')):'-'}</td><td class="row-actions"><button class="btn btn-sm" data-edit-admin="${esc(x.id)}">编辑</button>${x.role!=='superadmin'?` <button class="btn btn-sm danger" data-toggle-admin="${esc(x.id)}" data-enabled="${x.enabled?'true':'false'}">${x.enabled?'停用':'启用'}</button>`:''}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">暂无管理员账号。</td></tr>';return `<div class="panel-heading"><div><div class="eyebrow">系统设置</div><h2>管理员管理</h2><p class="muted">创建可登录后台的账号，并控制日常管理权限。</p></div><button class="btn primary" id="newAdminAccount">+ 添加管理员</button></div><div class="table-wrap"><table class="table admin-accounts-table"><thead><tr><th>管理员</th><th>权限</th><th>状态</th><th>最后更新</th><th>操作</th></tr></thead><tbody>${rows}</tbody></table></div><div id="adminAccountForm"></div>`}
function adminAccountForm(account){const editing=Boolean(account);return `<form id="adminAccountEditor" class="vehicle-editor admin-account-editor"><h3 class="full">${editing?'编辑管理员':'添加管理员'}</h3><p class="muted full">账号只能使用英文、数字、下划线、点或短横线，密码长度为 8 至 128 个字符。</p><label>管理员账号<input name="username" required minlength="3" maxlength="32" pattern="[A-Za-z0-9][A-Za-z0-9_.-]{2,31}" value="${editing?esc(account.username):''}" ${editing?'':'autocapitalize="none"'} placeholder="例如 sales_admin"></label><label>管理员姓名<input name="name" required maxlength="60" value="${editing?esc(account.name):''}" placeholder="例如 销售管理员"></label><label>登录密码<input type="password" name="password" ${editing?'':'required'} minlength="8" maxlength="128" autocomplete="new-password" placeholder="${editing?'留空表示不修改':'请输入登录密码'}"></label><label>确认密码<input type="password" name="confirmPassword" ${editing?'':'required'} minlength="8" maxlength="128" autocomplete="new-password" placeholder="再次输入登录密码"></label>${editing&&account.role!=='superadmin'?`<label class="admin-enabled-check"><input type="checkbox" name="enabled" value="true" ${account.enabled?'checked':''}> 账号启用</label>`:''}<div class="editor-actions full"><button class="btn primary" type="submit">${editing?'保存修改':'创建账号'}</button><button class="btn" type="button" data-cancel-admin>取消</button><span class="muted" id="adminAccountResult" role="status"></span></div></form>`}
function bindAdminAccounts(){const container=$('#adminAccountForm'),open=account=>{container.innerHTML=adminAccountForm(account);container.querySelector('form').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target));if(e.target.elements.enabled)body.enabled=e.target.elements.enabled.checked;const id=account?.id;const r=await api(id?'/api/admin/accounts/'+encodeURIComponent(id):'/api/admin/accounts',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const out=$('#adminAccountResult');if(!r.ok){out.textContent=r.error||'保存失败';return}administratorAccounts=id?administratorAccounts.map(x=>x.id===id?r.admin:x):[...administratorAccounts,r.admin];container.innerHTML='';$('#adminPanel').innerHTML=adminAccountsPanel();bindAdminAccounts()}};$('#newAdminAccount')?.addEventListener('click',()=>open(null));document.querySelectorAll('[data-edit-admin]').forEach(b=>b.onclick=()=>open(administratorAccounts.find(x=>x.id===b.dataset.editAdmin)));document.querySelectorAll('[data-toggle-admin]').forEach(b=>b.onclick=async()=>{const account=administratorAccounts.find(x=>x.id===b.dataset.toggleAdmin);if(!account)return;if(!confirm(account.enabled?'确定停用这个管理员账号吗？':'确定启用这个管理员账号吗？'))return;const body={username:account.username,name:account.name,enabled:!account.enabled};const r=await api('/api/admin/accounts/'+encodeURIComponent(account.id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok){alert(r.error||'操作失败');return}administratorAccounts=administratorAccounts.map(x=>x.id===account.id?r.admin:x);$('#adminPanel').innerHTML=adminAccountsPanel();bindAdminAccounts()});container?.addEventListener('click',e=>{if(e.target.closest('[data-cancel-admin]'))container.innerHTML=''})}
function vehiclePanel(){return `<div class="panel-heading"><div><div class="eyebrow">内容管理</div><h2>车辆管理</h2><p class="muted">管理前台展示的车辆、价格、照片和详细参数。</p></div><button class="btn primary" id="addVehicle">+ 添加车辆</button></div><div class="table-wrap"><table class="table"><thead><tr><th>车辆信息</th><th>价格</th><th>状态</th><th>推荐</th><th>操作</th></tr></thead><tbody>${vehicles.map(v=>`<tr><td><div class="table-title">${esc(v.title)}</div><small>${esc(v.brand||'')} · ${esc(v.year||'')} · ${Array.isArray(v.images)&&v.images.length?v.images.length:(v.image?1:0)} 张照片</small></td><td>${esc(v.price)}</td><td><span class="status status-${String(v.status||'').toLowerCase()}">${esc(v.status)}</span></td><td>${v.featured?'是':'-'}</td><td class="row-actions"><a class="btn btn-sm" href="#/vehicle/${v.id}" target="_blank">查看</a> <button class="btn btn-sm" data-edit-v="${v.id}">编辑</button> <button class="btn btn-sm danger" data-del-v="${v.id}">删除</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">暂无车辆，请先添加车辆。</td></tr>'}</tbody></table></div><div id="vehicleForm"></div>`}
function brandPanel(){const rows=brands.map(x=>`<tr><td>${x.logo?`<img class="brand-admin-logo" src="${esc(x.logo)}" alt="" loading="lazy">`:`<span class="brand-admin-mark">${esc((x.name||'?').slice(0,1).toUpperCase())}</span>`}</td><td><strong>${esc(x.name)}</strong></td><td>${esc(x.name_zh||'')}</td><td><code>${esc(x.slug||'')}</code></td><td class="row-actions"><button class="btn btn-sm" data-edit-brand="${esc(x.id)}">编辑</button> <button class="btn btn-sm danger" data-delete-brand="${esc(x.id)}">删除</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">暂无品牌。</td></tr>';return `<div class="panel-heading"><div><div class="eyebrow">车辆资料</div><h2>车辆品牌</h2><p class="muted">维护前台品牌筛选图标和中文名称。品牌名称需与车辆资料中的品牌一致。</p></div><button class="btn primary" id="addBrand">+ 添加品牌</button></div><div class="table-wrap"><table class="table brand-admin-table"><thead><tr><th>图标</th><th>英文品牌名</th><th>中文品牌名</th><th>标识</th><th>操作</th></tr></thead><tbody>${rows}</tbody></table></div><div id="brandForm"></div>`}
function upgradeVehicleBrandField(form,selected=''){const input=form?.elements?.brand;if(!input||input.tagName==='SELECT')return;const label=input.closest('label');if(!label)return;const select=document.createElement('select');select.name='brand';const options=[...brands];if(selected&&!options.some(item=>item.name===selected))options.push({name:selected,name_zh:''});options.sort((a,b)=>a.name.localeCompare(b.name));select.innerHTML='<option value="">请选择品牌</option>'+options.map(item=>`<option value="${esc(item.name)}">${esc(item.name)}${item.name_zh?`（${esc(item.name_zh)}）`:''}</option>`).join('');select.value=selected||'';label.replaceChildren(document.createTextNode('品牌'),select)}
function brandEditor(brand){const editing=Boolean(brand);return `<form id="brandEditor" class="vehicle-editor brand-editor"><div class="editor-section-title full">基本信息</div><p class="muted full">英文品牌名用于关联车辆数据；中文名用于中文界面。图标地址可留空，前台会显示品牌首字母。</p><label>英文品牌名<input name="name" required maxlength="60" value="${editing?esc(brand.name):''}" placeholder="例如 Toyota"></label><label>中文品牌名<input name="name_zh" maxlength="60" value="${editing?esc(brand.name_zh||''):''}" placeholder="例如 丰田"></label><label>品牌标识<input name="slug" required maxlength="60" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" value="${editing?esc(brand.slug):''}" placeholder="例如 toyota"></label><label class="full">品牌图标 HTTPS 地址<input name="logo" type="url" maxlength="500" value="${editing?esc(brand.logo||''):''}" placeholder="https://example.com/toyota.svg"></label><div class="editor-actions full"><button class="btn primary" type="submit">${editing?'保存修改':'保存品牌'}</button><button class="btn" type="button" data-cancel-brand>取消</button><span class="muted" id="brandSaveResult" role="status" aria-live="polite"></span></div></form>`}
function bindBrands(){
  const container=$('#brandForm');
  const open=brand=>{
    if(!container)return;
    container.innerHTML=brandEditor(brand);
    const form=container.querySelector('form');
    const modal=openVehicleEditorDialog(form,brand?'编辑车辆品牌':'添加车辆品牌',{className:'brand-edit-dialog',titleId:'brandEditDialogTitle'});
    if(!modal)return;
    form.querySelector('[data-cancel-brand]').onclick=modal.close;
    form.onsubmit=async e=>{
      e.preventDefault();
      if(form.dataset.saving==='1')return;
      const result=form.querySelector('#brandSaveResult'),button=form.querySelector('button[type="submit"]'),data=Object.fromEntries(new FormData(form));
      if(data.logo&&!data.logo.startsWith('https://')){result.textContent='品牌图标地址必须使用 HTTPS';return}
      form.dataset.saving='1';button.disabled=true;result.textContent='正在保存…';
      try{
        const id=brand?.id,response=await api(id?'/api/brands/'+encodeURIComponent(id):'/api/brands',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
        if(!response.ok){result.textContent=response.error||'保存失败';return}
        brands=await api('/api/brands');
        if(!form.isConnected)return;
        modal.close();$('#adminPanel').innerHTML=brandPanel();bindBrands();applyLanguage('zh');
      }catch{result.textContent='网络异常，请稍后重试'}
      finally{delete form.dataset.saving;if(button.isConnected)button.disabled=false}
    };
  };
  $('#addBrand')?.addEventListener('click',()=>open(null));
  document.querySelectorAll('[data-edit-brand]').forEach(button=>button.onclick=()=>{const brand=brands.find(x=>String(x.id)===button.dataset.editBrand);if(brand)open(brand)});
  document.querySelectorAll('[data-delete-brand]').forEach(button=>button.onclick=async()=>{const brand=brands.find(x=>String(x.id)===button.dataset.deleteBrand);if(!brand||!confirm(`确定删除品牌“${brand.name_zh||brand.name}”吗？已有车辆资料不会删除，但该品牌筛选图标将不再显示。`))return;const response=await api('/api/brands/'+encodeURIComponent(brand.id),{method:'DELETE'});if(!response.ok){alert(response.error||'删除失败');return}brands=await api('/api/brands');$('#adminPanel').innerHTML=brandPanel();bindBrands()});
}
function contactPanel(){return `<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:18px"><h2>销售联系人</h2><button class="btn primary" id="addContact">+ 添加联系人</button></div><table class="table"><thead><tr><th>姓名</th><th>职位</th><th>电话</th><th>操作</th></tr></thead><tbody>${contacts.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.role)}</td><td>${esc(c.phone)}</td><td><button class="btn" data-edit-c="${c.id}">编辑</button> <button class="btn" data-del-c="${c.id}">删除</button></td></tr>`).join('')}</tbody></table><div id="contactForm"></div>`}
let inquiries=[];
function inquiryPanel(){return `<h2>卖车咨询</h2><table class="table"><thead><tr><th>姓名</th><th>电话</th><th>车辆</th><th>年份 / 里程</th><th>补充说明</th><th>提交时间</th><th>操作</th></tr></thead><tbody>${inquiries.map(x=>`<tr><td>${esc(x.name)}</td><td><a href="tel:${esc(x.phone)}">${esc(x.phone)}</a></td><td>${esc(x.vehicle)}</td><td>${esc(x.yearMileage)}</td><td style="white-space:pre-wrap;max-width:260px">${esc(x.message)}</td><td>${esc(x.createdAt)}</td><td><button class="btn" data-del-i="${x.id}">删除</button></td></tr>`).join('')||'<tr><td colspan="7">暂无卖车咨询</td></tr>'}</tbody></table>`}
function salesLinksPanel(){const rows=salesLinks.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${esc(x.phone)}</td><td>${esc(x.whatsapp)}</td><td><code>/sales/${esc(x.slug)}</code></td><td><button class="btn btn-sm" data-copy-sales="${esc(x.slug)}">复制链接</button> <button class="btn btn-sm" data-edit-sales="${esc(x.slug)}">编辑</button> <button class="btn btn-sm danger" data-delete-sales="${esc(x.slug)}">删除</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">暂无销售人员，请点击右上角新建。</td></tr>';return `<div class="panel-heading"><div><div class="eyebrow">销售渠道</div><h2>销售人员专属链接</h2><p class="muted">每个销售人员拥有独立主页链接，共享同一车辆库。</p></div><button class="btn primary" id="newSalesLink">+ 新建销售人员专属链接</button></div><div class="table-wrap"><table class="table"><thead><tr><th>销售人员</th><th>电话</th><th>WhatsApp</th><th>专属链接</th><th>操作</th></tr></thead><tbody>${rows}</tbody></table></div><div id="salesLinkForm"></div>`}function passwordPanel(){return `<div class="panel-heading"><div><h2>修改我的密码</h2><p class="muted">当前账号：${esc(currentAdmin?.username)}。新密码长度为 8 至 128 个字符，保存后需要重新登录。</p></div></div><form id="passwordForm" class="form admin-account-form password-account-form"><label>当前密码<input type="password" name="currentPassword" required maxlength="128" autocomplete="current-password" placeholder="请输入当前密码"></label><label>新密码<input type="password" name="newPassword" required minlength="8" maxlength="128" autocomplete="new-password" placeholder="请输入新密码"></label><label>确认新密码<input type="password" name="confirmPassword" required minlength="8" maxlength="128" autocomplete="new-password" placeholder="再次输入新密码"></label><button class="btn primary" type="submit">保存新密码</button><p id="passwordResult" class="form-feedback" role="status"></p></form>`}
function bindAdmin(){
  const panel=$('#adminPanel');
  const wirePassword=()=>$('#passwordForm')?.addEventListener('submit',async e=>{
    e.preventDefault();const out=$('#passwordResult'),button=e.target.querySelector('button');button.disabled=true;out.textContent='正在保存…';
    try{const r=await api('/api/admin/password',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});if(r.ok){alert('密码已修改，请使用账号和新密码重新登录。');await render()}else out.textContent=r.error||'修改失败'}catch{out.textContent='网络异常，请稍后重试'}finally{button.disabled=false}
  });
  const show=async tab=>{
    document.querySelectorAll('.side-tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));
    const titles={dashboard:'概览',vehicles:'车辆管理',brands:'车辆品牌',inquiries:'卖车咨询',salesLinks:'销售链接',accounts:'管理员管理',password:'修改密码'};
    $('#adminTitle').textContent=titles[tab]||'概览';
    if(tab==='dashboard')panel.innerHTML=dashboardPanel();
    else if(tab==='vehicles')panel.innerHTML=vehiclePanel();
    else if(tab==='brands')panel.innerHTML=brandPanel();
    else if(tab==='inquiries'){inquiries=await api('/api/inquiries');panel.innerHTML=inquiryPanel()}
    else if(tab==='password')panel.innerHTML=passwordPanel();
    else if(tab==='salesLinks')panel.innerHTML=salesLinksPanel();
    else if(tab==='accounts'){
      panel.innerHTML='<p class="muted">正在加载管理员列表…</p>';
      try{const result=await api('/api/admin/accounts');if(!Array.isArray(result.admins)){panel.innerHTML='<p class="form-feedback" role="alert"></p>';panel.querySelector('p').textContent=result.error||'加载管理员失败';return}administratorAccounts=result.admins;panel.innerHTML=adminAccountsPanel();bindAdminAccounts()}catch{panel.innerHTML='<p class="form-feedback" role="alert">加载失败，请检查网络后重新进入。</p>'}
    }
    bindPanel();bindSalesLinks();bindBrands();wirePassword();applyLanguage('zh');
  };
  document.querySelectorAll('.side-tab').forEach(t=>t.onclick=()=>show(t.dataset.tab));
  document.querySelectorAll('[data-quick-add]').forEach(b=>b.onclick=()=>{show(b.dataset.tab).then(()=>document.querySelector(b.dataset.quickAdd==='vehicle'?'#addVehicle':'#addContact')?.click())});
  show('dashboard');applyLanguage('zh');
}
function bindSalesLinks(){const render=()=>{$('#adminPanel').innerHTML=salesLinksPanel();bindSalesLinks()};const save=async data=>{const r=await api('/api/sales-links',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!r.ok){alert(r.error||'保存失败');return false}salesLinks=r.salesLinks;render();return true};$('#newSalesLink')?.addEventListener('click',()=>{$('#salesLinkForm').innerHTML=`<form class="vehicle-editor sales-link-editor" id="newSalesForm"><h3 class="full">新建销售人员专属链接</h3><label>链接标识<input name="slug" required pattern="[A-Za-z0-9-]+" placeholder="例如 alex"></label><label>销售人员名称<input name="name" required placeholder="例如 Alex"></label><label>电话号码<input name="phone" required placeholder="+1 202 555 0101"></label><label>WhatsApp号码<input name="whatsapp" required placeholder="+1 202 555 0101"></label><div class="editor-actions"><button class="btn primary">创建链接</button></div></form>`;$('#newSalesForm').onsubmit=async e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));await save([...salesLinks,x])}});document.querySelectorAll('[data-edit-sales]').forEach(b=>b.onclick=()=>{const x=salesLinks.find(v=>v.slug===b.dataset.editSales);if(!x)return;$('#salesLinkForm').innerHTML=`<form class="vehicle-editor sales-link-editor" id="editSalesForm"><h3 class="full">编辑销售人员专属链接</h3><label>链接标识<input name="slug" required pattern="[A-Za-z0-9-]+" value="${esc(x.slug)}"></label><label>销售人员名称<input name="name" required value="${esc(x.name)}"></label><label>电话号码<input name="phone" required value="${esc(x.phone)}"></label><label>WhatsApp号码<input name="whatsapp" required value="${esc(x.whatsapp)}"></label><div class="editor-actions"><button class="btn primary">保存修改</button></div></form>`;$('#editSalesForm').onsubmit=async e=>{e.preventDefault();const n=Object.fromEntries(new FormData(e.target));await save(salesLinks.map(v=>v.slug===x.slug?n:v))}});document.querySelectorAll('[data-delete-sales]').forEach(b=>b.onclick=async()=>{if(!confirm('确定删除这个销售专属链接吗？'))return;await save(salesLinks.filter(x=>x.slug!==b.dataset.deleteSales))});document.querySelectorAll('[data-copy-sales]').forEach(b=>b.onclick=async()=>{const url=location.origin+'/sales/'+b.dataset.copySales;try{await navigator.clipboard.writeText(url);alert('链接已复制：'+url)}catch{const ta=document.createElement('textarea');ta.value=url;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();alert('链接已复制：'+url)}})}function bindPanel(){document.querySelectorAll('[data-del-v]').forEach(b=>b.onclick=async()=>{await api('/api/vehicles/'+b.dataset.delV,{method:'DELETE'});vehicles=await api('/api/vehicles');$('#adminPanel').innerHTML=vehiclePanel();bindPanel();applyLanguage('zh')});document.querySelectorAll('[data-del-c]').forEach(b=>b.onclick=async()=>{await api('/api/contacts/'+b.dataset.delC,{method:'DELETE'});contacts=await api('/api/contacts');$('#adminPanel').innerHTML=contactPanel();bindPanel();applyLanguage('zh')});document.querySelectorAll('[data-del-i]').forEach(b=>b.onclick=async()=>{await api('/api/inquiries/'+b.dataset.delI,{method:'DELETE'});inquiries=await api('/api/inquiries');$('#adminPanel').innerHTML=inquiryPanel();bindPanel()});$('#settingsForm')?.addEventListener('submit',async e=>{e.preventDefault();const result=await api('/api/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});$('#settingsResult').textContent=result.ok?'设置已保存':'保存失败'});$('#addVehicle')?.addEventListener('click',()=>{$('#vehicleForm').innerHTML=`<form class="form" style="margin-top:20px" id="vf"><input name="title" required placeholder="车辆标题"><input name="brand" placeholder="品牌"><input name="model" placeholder="车型"><select name="bodyType"><option value="">车型分类</option><option>Sedan</option><option>Hatchback</option><option>SUV</option><option>Crossover</option><option>MPV / Minivan</option><option>Pickup Truck</option><option>Van</option><option>Truck</option><option>Electric Vehicle</option></select><input name="year" placeholder="年份"><input name="mileage" type="number" min="0" placeholder="里程"><select name="mileageUnit"><option value="km">公里（km）</option><option value="mi">英里（mi）</option></select><input name="price" type="number" min="0" step="0.01" placeholder="价格"><select name="currency"><option>USD</option><option>NGN</option><option>IDR</option><option>THB</option><option>MYR</option><option>PHP</option><option>VND</option></select><input name="transmission" placeholder="变速箱"><select name="fuelType"><option value="">燃料类型</option><option>Petrol</option><option>Diesel</option><option>Hybrid</option><option>Electric</option></select><select name="driveType"><option value="">驱动方式</option><option>FWD</option><option>RWD</option><option>AWD</option><option>4WD</option></select><select name="steering"><option value="">方向盘</option><option value="Left Hand Drive">左舵</option><option value="Right Hand Drive">右舵</option></select><select name="condition"><option value="Used">二手</option><option value="New">新车</option><option value="Certified Used">认证二手车</option></select><input name="location" placeholder="所在地"><select name="status"><option value="Available">在售</option><option value="Reserved">已预订</option><option value="Sold">已售</option></select><select name="contact_id"><option value="">不指定联系人</option>${contacts.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><label class="full">车辆照片（最多20张，每张12MB；编辑时选择新照片会替换原图，不选则保留） <input type="file" multiple name="photos" accept="image/jpeg,image/png,image/webp,image/gif"></label><input class="full" name="image" placeholder="或填写图片链接"><label><input type="checkbox" name="featured" value="true"> 首页推荐</label><textarea class="full" name="description" placeholder="车辆描述"></textarea><button class="btn primary">保存车辆</button></form>`;$('#vf').onsubmit=async e=>{e.preventDefault();if(e.target.dataset.editId)return;if(!validatePhotos(e.target))return;const result=await api('/api/vehicles',{method:'POST',body:new FormData(e.target)});if(result.error){alert(result.error);return;}vehicles=await api('/api/vehicles');$('#adminPanel').innerHTML=vehiclePanel();bindPanel();applyLanguage('zh')}});$('#addContact')?.addEventListener('click',()=>{$('#contactForm').innerHTML=`<form class="form" style="margin-top:20px" id="cf"><input name="name" required placeholder="姓名"><input name="role" placeholder="职位"><input name="phone" placeholder="电话"><input name="whatsapp" placeholder="WhatsApp"><input name="email" placeholder="电子邮箱"><button class="btn primary">保存联系人</button></form>`;$('#cf').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));await api('/api/contacts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});contacts=await api('/api/contacts');$('#adminPanel').innerHTML=contactPanel();bindPanel();applyLanguage('zh')}})}
async function render(){const p=location.hash.slice(1)||(location.pathname==='/admin'?'/admin':'/'),isSalesPage=Boolean(salesSlug());if(p!=='/admin'&&(p!=='/'||isSalesPage)){try{siteSettings=await api('/api/settings');salesLinks=await api('/api/sales-links');activeSales=salesLinks.find(x=>x.slug===salesSlug())||null}catch{siteSettings={};salesLinks=[];activeSales=null}}let html;if(p==='/')html=isSalesPage?await home():'';else if(p==='/cars')html=await cars();else if(p==='/about')html=about();else if(p==='/sell')html=sell();else if(p==='/admin')html=await admin();else if(p.startsWith('/vehicle/'))html=await detail(p.split('/')[2]);$('#app').innerHTML=html===undefined?await home():html;const pageLanguage=p==='/admin'?'zh':(language||'en');document.documentElement.lang=pageLanguage==='zh'?'zh-CN':pageLanguage;applyLanguage(pageLanguage);if(p!=='/admin'&&(p!=='/'||isSalesPage))$('#languageSwitch').onchange=()=>{language=$('#languageSwitch').value;localStorage.setItem('dealer-language',language);render()};if(p==='/admin'){if($('#loginForm'))$('#loginForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button'),out=$('#loginError');button.disabled=true;button.textContent='正在登录…';out.textContent='';try{const r=await api('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});if(r.ok)await render();else out.textContent=r.error||'账号或密码错误'}catch{out.textContent='网络异常，请稍后重试'}finally{button.disabled=false;button.textContent='登录'}};else{bindAdmin();applyLanguage('zh');new MutationObserver(()=>applyLanguage('zh')).observe($('#adminPanel'),{childList:true,subtree:true});$('#logout').onclick=async()=>{await api('/api/admin/logout',{method:'POST'});render()}}}if(p==='/cars'){$('#q').oninput=()=>filterCars();$('#status').onchange=()=>filterCars();initBrandFilter()}}
function parseVehicleNumber(value){if(typeof value==='number')return Number.isFinite(value)?value:NaN;let raw=String(value??'').trim().replace(/[^\d.,+-]/g,'');if(!raw)return NaN;const sign=raw.startsWith('-')?-1:1;raw=raw.replace(/[+-]/g,'');const comma=raw.lastIndexOf(','),dot=raw.lastIndexOf('.');if(comma>=0&&dot>=0){const decimal=comma>dot?',':'.',group=decimal===','?'.':',';raw=raw.split(group).join('');const index=raw.lastIndexOf(decimal);raw=raw.slice(0,index).split(decimal).join('')+'.'+raw.slice(index+1)}else{const separator=comma>=0?',':dot>=0?'.':'';if(separator){const parts=raw.split(separator),last=parts.pop();raw=parts.length>1||last.length===3?parts.join('')+last:parts.join('')+'.'+last}}const number=Number(raw);return Number.isFinite(number)?number*sign:NaN}
function brandMatches(value,selected){if(!selected)return true;const key=brandKey(value),brand=publicBrandCatalog.find(item=>item.slug===selected||[item.name,item.name_zh,...(item.aliases||[])].some(alias=>brandKey(alias)===brandKey(selected)));return brand?[brand.name,brand.name_zh,brand.slug,...(brand.aliases||[])].some(alias=>brandKey(alias)===key):key===brandKey(selected)}
function filterCars(){const q=(document.querySelector("#q")?.value||"").toLowerCase(),s=document.querySelector("#status")?.value||"",brand=document.querySelector("#brand")?.value||"",body=document.querySelector("#bodyType")?.value||"",fuel=document.querySelector("#fuelType")?.value||"",range=document.querySelector("#priceRange")?.value||"",year=document.querySelector("#yearFilter")?.value||"",sort=document.querySelector("#sort")?.value||"newest",[minPrice,maxPrice]=range?range.split('-').map(part=>part===''?null:parseVehicleNumber(part)):[null,null];let list=vehicles.filter(v=>{const price=parseVehicleNumber(v.price),priceMatches=!range||Number.isFinite(price)&&(minPrice===null||price>=minPrice)&&(maxPrice===null||price<maxPrice);return(!q||((v.brand||"")+" "+(v.model||"")+" "+(v.title||"")).toLowerCase().includes(q))&&(!s||v.status===s)&&brandMatches(v.brand,brand)&&(!body||v.bodyType===body)&&(!fuel||v.fuelType===fuel||v.fuel===fuel)&&(!year||normalizeVehicleYear(v.year)===year)&&priceMatches});const compareNumeric=(field,direction)=>(a,b)=>{const left=parseVehicleNumber(a[field]),right=parseVehicleNumber(b[field]),leftValid=Number.isFinite(left),rightValid=Number.isFinite(right);if(leftValid!==rightValid)return leftValid?-1:1;if(!leftValid)return Number(b.id||0)-Number(a.id||0);return(left-right)*direction||Number(b.id||0)-Number(a.id||0)};if(sort==='price-low')list.sort(compareNumeric('price',1));else if(sort==='price-high')list.sort(compareNumeric('price',-1));else if(sort==='year-new')list.sort(compareNumeric('year',-1));else if(sort==='mileage-low')list.sort(compareNumeric('mileage',1));else list.sort((a,b)=>Number(b.id||0)-Number(a.id||0));const grid=document.querySelector("#cargrid");if(grid)grid.innerHTML=list.map(card).join("")||`<div class="empty">${esc(ft('noVehicles'))}</div>`;const count=document.querySelector("#carCount");if(count)count.textContent=String(list.length)}
document.addEventListener('change',e=>{if(e.target.matches('#sort,#brand,#priceRange,#bodyType,#fuelType,#yearFilter'))filterCars()});
document.addEventListener('submit',async e=>{if(e.target.id!=='sellForm')return;e.preventDefault();const result=$('#sellResult');try{const response=await api('/api/inquiries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});result.textContent=response.ok?'Thank you. Your request has been received.':'Submission failed. Please try again later.';if(response.ok)e.target.reset()}catch{result.textContent='Submission failed. Please try again later.'}});window.addEventListener('hashchange',render);if(language)render();else api('/api/locale').then(result=>{language=result.language||'en';render()}).catch(()=>{language='en';render()});
function cardLocalized(v){const cover=vehicleImageList(v)[0]||'';return `<a class="card" href="#/vehicle/${v.id}"><img class="card-img" src="${esc(cover)}" alt="${esc(localized(v,'title'))}" loading="lazy"><div class="card-body"><h3>${esc(localized(v,'title'))}</h3><div class="meta"><span>${esc(v.year)}</span><span>•</span><span>${esc(v.mileage)} ${esc(v.mileageUnit||'')}</span><span>${esc(vehicleTerm(v.bodyType||v.fuelType||''))}</span></div><div class="card-bottom"><div class="price">${priceMarkup(v)}</div><span class="inquiry-pill">${esc(ft('inquire'))}</span></div></div></a>`}
async function detail(id){const v=await api('/api/vehicles/'+id),whatsapp=whatsappNumber(salesWhatsApp()||v.whatsapp||v.phone||'12025550188');return layout(`<main class="page shell"><a class="muted" href="#/cars">← Back to inventory</a><div class="detail" style="margin-top:22px">${vehicleGallery(v)}<div><div class="eyebrow">${esc(v.status)}</div><h1>${esc(localized(v,'title'))}</h1><div class="price" style="font-size:28px">${priceMarkup(v)}</div><div class="specs">${detailSpecs(v)}</div><p class="muted" style="line-height:1.7">${esc(localized(v,'description'))}</p><div class="actions"><a class="btn primary" href="https://wa.me/${whatsapp}">WhatsApp sales</a><a class="btn" href="tel:${esc(salesPhone()||v.phone||'12025550188')}">Call us</a></div></div></div></main>`)}
document.addEventListener('click',e=>{if(!e.target.closest('#addVehicle'))return;const form=$('#vf');if(!form||form.dataset.i18n)return;form.dataset.i18n='1';form.insertAdjacentHTML('afterbegin','<input name="title_zh" placeholder="中文标题"><input name="title_en" placeholder="英文标题"><textarea name="description_zh" class="full" rows="3" placeholder="中文描述"></textarea><textarea name="description_en" class="full" rows="3" placeholder="英文描述"></textarea>')});
document.addEventListener('click',e=>{const b=e.target.closest('[data-quick-add]');if(!b)return;const tab=document.querySelector(`.side-tab[data-tab="${b.dataset.tab}"]`);if(tab)tab.click();setTimeout(()=>document.querySelector(b.dataset.quickAdd==='vehicle'?'#addVehicle':'#addContact')?.click(),80)});
document.addEventListener('click',e=>{const b=e.target.closest('.quick-actions [data-tab]:not([data-quick-add])');if(!b)return;document.querySelector(`.side-tab[data-tab="${b.dataset.tab}"]`)?.click()});
function openVehicleEditorDialog(form,title='编辑车辆资料',options={}){const panel=$('#adminPanel');if(!panel||!form)return;const previousFocus=document.activeElement,titleId=options.titleId||'vehicleEditDialogTitle',dialog=document.createElement('dialog');dialog.className='vehicle-edit-dialog'+(options.className?' '+options.className:'');dialog.setAttribute('aria-labelledby',titleId);dialog.innerHTML=`<div class="vehicle-edit-dialog-head"><strong id="${esc(titleId)}"></strong><button class="vehicle-edit-close" type="button" aria-label="关闭" data-close-vehicle-edit>×</button></div><div class="vehicle-edit-dialog-body"></div>`;dialog.querySelector('#'+titleId).textContent=title;dialog.querySelector('.vehicle-edit-dialog-body').appendChild(form);panel.appendChild(dialog);const close=()=>{cleanupVehiclePhotoManager(form);dialog.close();dialog.remove();if(previousFocus?.isConnected)previousFocus.focus({preventScroll:true})};dialog.querySelector('[data-close-vehicle-edit]').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close()});dialog.addEventListener('click',e=>{if(e.target===dialog)close()});dialog.showModal();form.querySelector('input:not([type="file"]),select,textarea')?.focus({preventScroll:true});return {dialog,close}}
function moveVehiclePhoto(items,id,destination){const from=items.findIndex(item=>item.id===id);if(from<0)return false;const to=Math.max(0,Math.min(items.length-1,destination));if(from===to)return false;const [item]=items.splice(from,1);items.splice(to,0,item);return true}
function vehiclePhotoPayload(items){const uploads=items.filter(item=>item.kind==='upload');return {uploads,order:items.map(item=>item.kind==='upload'?`upload:${uploads.indexOf(item)}`:item.ref)}}
function vehiclePhotoOrderMatches(vehicle,order){const images=vehicle?.images;if(!Array.isArray(order)||!Array.isArray(images)||images.length!==order.length||new Set(images).size!==images.length||vehicle.image!==(images[0]||''))return false;const existing=new Set(order.filter(ref=>!/^upload:(?:0|[1-9]\d*)$/.test(ref)));return order.every((ref,index)=>/^upload:(?:0|[1-9]\d*)$/.test(ref)?!!safePhoto(images[index])&&!existing.has(images[index]):images[index]===ref)}
function cleanupVehiclePhotoManager(form){const state=form?._photoManager;if(!state)return;state.items.filter(item=>item.kind==='upload').forEach(item=>URL.revokeObjectURL(item.src));delete form._photoManager}
function syncVehiclePhotoLink(form){const state=form?._photoManager,input=form?.elements.image;if(!state||!input)return true;const value=input.value.trim(),current=state.items.find(item=>item.kind==='link');if(current?.ref===value||(!current&&!value))return true;if(value){try{const url=new URL(value);if(!['https:','http:'].includes(url.protocol)||url.username||url.password||value.length>2048)throw new Error()}catch{state.message='图片链接必须是有效的 HTTP 或 HTTPS 地址。';renderVehiclePhotoManager(form);input.focus();return false}if(!current&&state.items.length>=20){state.message='最多保留20张照片，请先移除本次待上传的照片。';renderVehiclePhotoManager(form);return false}}if(current){if(value){current.ref=value;current.src=value}else state.items.splice(state.items.indexOf(current),1)}else if(value)state.items.push({id:`link-${state.nextId++}`,kind:'link',ref:value,src:value,name:'图片链接'});state.message='';renderVehiclePhotoManager(form);return true}
function renderVehiclePhotoManager(form){const state=form?._photoManager;if(!state)return;const grid=state.host.querySelector('[data-photo-grid]');grid.innerHTML=state.items.map((item,index)=>`<article class="photo-manager-card${index===0?' is-cover':''}" data-photo-id="${esc(item.id)}" draggable="true"><div class="photo-manager-image"><img src="${esc(item.src)}" alt="车辆照片 ${index+1}" draggable="false"><span class="photo-image-fallback">图片暂时无法加载</span><span class="photo-position">${index+1}</span>${index===0?'<span class="photo-cover-badge">首图</span>':''}${item.kind==='upload'?'<span class="photo-pending-badge">待上传</span>':''}<span class="photo-drag-handle" aria-hidden="true" title="拖动调整顺序">&#8942;&#8942;</span></div><div class="photo-manager-name" title="${esc(item.name)}">${esc(item.name)}</div><div class="photo-card-actions"><button class="photo-cover-button" type="button" data-photo-action="cover" ${index===0?'disabled':''} aria-label="将第 ${index+1} 张照片设为首图">${index===0?'当前首图':'设为首图'}</button><button type="button" data-photo-action="previous" ${index===0?'disabled':''} aria-label="将第 ${index+1} 张照片前移">前移</button><button type="button" data-photo-action="next" ${index===state.items.length-1?'disabled':''} aria-label="将第 ${index+1} 张照片后移">后移</button>${item.kind!=='existing'?'<button class="photo-remove-button" type="button" data-photo-action="remove" aria-label="移除此张待保存照片">移除</button>':''}</div></article>`).join('')||'<div class="photo-manager-empty"><strong>还没有车辆照片</strong><span>点击“添加照片”，可一次选择多张，也可分批追加。</span></div>';state.host.querySelector('[data-photo-count]').textContent=`${state.items.length} / 20 张`;const uploadCount=state.items.filter(item=>item.kind==='upload').length;state.host.querySelector('[data-photo-summary]').textContent=uploadCount?`本次新增 ${uploadCount} 张，保存时一并上传`:'第一张是前台列表和详情页的首图';const status=state.host.querySelector('[data-photo-status]');status.textContent=state.message||'';status.classList.toggle('is-error',!!state.message);const input=state.host.querySelector('[data-photo-input]');input.disabled=state.items.length>=20}
function addVehiclePhotos(form,files){const state=form?._photoManager;if(!state)return false;const selected=Array.from(files||[]);if(!selected.length)return true;if(state.items.length+selected.length>20||selected.some(file=>file.size>12*1024*1024||!/^image\/(jpeg|png|webp|gif)$/.test(file.type))){state.message='最多保留20张JPEG、PNG、WebP或GIF照片，每张不超过12MB。';renderVehiclePhotoManager(form);return false}selected.forEach(file=>state.items.push({id:`upload-${state.nextId++}`,kind:'upload',file,src:URL.createObjectURL(file),name:file.name||'新增照片'}));state.message='';renderVehiclePhotoManager(form);return true}
function setupVehiclePhotoManager(form,images=[]){
  const host=form.querySelector('[data-photo-manager]');if(!host)return;
  cleanupVehiclePhotoManager(form);
  const state={host,items:[...new Set(images)].map((ref,index)=>({id:`existing-${index}`,kind:'existing',ref,src:ref,name:`已上传照片 ${index+1}`})),nextId:0,dragId:'',message:''};
  form._photoManager=state;
  host.innerHTML='<div class="photo-manager-head"><div><strong>车辆照片</strong><p>拖动图片或使用前移、后移调整顺序，第一张自动作为首图。</p></div><span class="photo-count" data-photo-count></span></div><label class="photo-manager-upload"><span class="photo-upload-icon" aria-hidden="true">+</span><span><strong>添加照片</strong><small>支持多次追加，JPEG / PNG / WebP / GIF，单张不超过 12MB</small></span><input type="file" multiple name="photos" data-photo-input accept="image/jpeg,image/png,image/webp,image/gif"></label><div class="photo-manager-grid" data-photo-grid></div><div class="photo-manager-footer"><span data-photo-summary></span><span>，最多 20 张，保存后按此顺序展示</span></div><div class="photo-manager-status" data-photo-status role="status" aria-live="polite"></div>';
  host.addEventListener('change',event=>{
    if(!event.target.matches('[data-photo-input]'))return;
    addVehiclePhotos(form,event.target.files);event.target.value='';
  });
  host.addEventListener('click',event=>{
    const button=event.target.closest('[data-photo-action]');if(!button||button.disabled)return;
    const card=button.closest('[data-photo-id]'),index=state.items.findIndex(item=>item.id===card?.dataset.photoId);if(index<0)return;
    const action=button.dataset.photoAction,id=state.items[index].id;
    if(action==='remove'){
      const item=state.items[index];if(item.kind==='existing')return;
      if(item.kind==='upload')URL.revokeObjectURL(item.src);else if(form.elements.image)form.elements.image.value='';
      state.items.splice(index,1);
    }else moveVehiclePhoto(state.items,id,action==='cover'?0:index+(action==='previous'?-1:1));
    state.message='';renderVehiclePhotoManager(form);
    const focusId=action==='remove'?state.items[Math.min(index,state.items.length-1)]?.id:id;
    const focusCard=focusId?host.querySelector(`[data-photo-id="${focusId}"]`):null;
    const focusButton=focusCard?.querySelector(`[data-photo-action="${action}"]:not(:disabled)`)||focusCard?.querySelector('button:not(:disabled)');
    (focusButton||host.querySelector('[data-photo-input]'))?.focus?.({preventScroll:true});
  });
  host.addEventListener('error',event=>{if(event.target.tagName==='IMG')event.target.closest('.photo-manager-card')?.classList.add('is-broken')},true);
  host.addEventListener('dragstart',event=>{
    const card=event.target.closest('[data-photo-id]');if(!card||event.target.closest('button')){event.preventDefault();return}
    state.dragId=card.dataset.photoId;card.classList.add('is-dragging');
    if(event.dataTransfer){event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',state.dragId)}
  });
  host.addEventListener('dragover',event=>{
    const card=event.target.closest('[data-photo-id]');if(!state.dragId||!card)return;
    event.preventDefault();if(event.dataTransfer)event.dataTransfer.dropEffect='move';
    host.querySelectorAll('.is-drop-target').forEach(item=>item.classList.remove('is-drop-target'));
    if(card.dataset.photoId!==state.dragId)card.classList.add('is-drop-target');
  });
  host.addEventListener('drop',event=>{
    const card=event.target.closest('[data-photo-id]');if(!state.dragId||!card)return;
    event.preventDefault();const target=state.items.findIndex(item=>item.id===card.dataset.photoId);
    moveVehiclePhoto(state.items,state.dragId,target);state.dragId='';state.message='';renderVehiclePhotoManager(form);
  });
  host.addEventListener('dragend',()=>{state.dragId='';host.querySelectorAll('.is-dragging,.is-drop-target').forEach(item=>item.classList.remove('is-dragging','is-drop-target'))});
  form.elements.image?.addEventListener('change',()=>syncVehiclePhotoLink(form));
  renderVehiclePhotoManager(form);
}
function vehicleEditorFormData(form){const body=new FormData(form),state=form._photoManager;body.delete('photos');body.delete('main_image');body.delete('main_photo_index');body.set('featured',form.elements.featured?.checked?'true':'false');if(state){const payload=vehiclePhotoPayload(state.items);payload.uploads.forEach(item=>body.append('photos',item.file,item.file.name));body.set('photo_order',JSON.stringify(payload.order))}return body}
function vehicleEditorMarkup(editing){return `<div class="full editor-intro"><span class="eyebrow">车辆资料</span><h3>${editing?'编辑车辆':'添加车辆'}</h3><p>车辆资料、照片顺序与首图一次保存；新增照片会追加，不会覆盖旧图。</p></div><div class="editor-section-title full">基本信息</div><input type="hidden" name="title"><label>中文标题<input name="title_zh" placeholder="例如：精品二手 BMW 5系"></label><label>英文标题<input name="title_en" placeholder="例如：BMW 5 Series"></label><label>品牌<input name="brand" placeholder="BMW"></label><label>车型<input name="model" placeholder="例如 Corolla"></label><label>车型分类<select name="bodyType"><option value="">请选择</option><option>Sedan</option><option>Hatchback</option><option>SUV</option><option>Crossover</option><option>MPV / Minivan</option><option>Pickup Truck</option><option>Van</option><option>Truck</option><option>Electric Vehicle</option></select></label><label>年份<input name="year" placeholder="2024"></label><label>里程<input name="mileage" type="number" min="0" placeholder="例如 32400"></label><label>里程单位<select name="mileageUnit"><option value="km">公里（km）</option><option value="mi">英里（mi）</option></select></label><label>价格<input name="price" type="number" min="0" step="0.01" placeholder="例如 32000"></label><label>货币<select name="currency"><option>USD</option><option>NGN</option><option>IDR</option><option>THB</option><option>MYR</option><option>PHP</option><option>VND</option></select></label><label>变速箱<input name="transmission" placeholder="Automatic"></label><label>排量<input name="displacement" placeholder="例如 1.5L / 2.0T / 1498cc" maxlength="40"></label><label>燃料类型<select name="fuelType"><option value="">请选择</option><option>Petrol</option><option>Diesel</option><option>Hybrid</option><option>Electric</option></select></label><label>驱动方式<select name="driveType"><option value="">请选择</option><option>FWD</option><option>RWD</option><option>AWD</option><option>4WD</option></select></label><label>方向盘<select name="steering"><option value="">请选择</option><option value="Left Hand Drive">左舵</option><option value="Right Hand Drive">右舵</option></select></label><label>车况<select name="condition"><option value="Used">二手</option><option value="New">新车</option><option value="Certified Used">认证二手车</option></select></label><label>所在地<input name="location" placeholder="城市 / 国家"></label><label>状态<select name="status"><option value="Available">在售</option><option value="Reserved">已预订</option><option value="Sold">已售</option></select></label><label>销售联系人<select name="contact_id"><option value="">不指定联系人</option>${contacts.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><div class="editor-section-title full">车辆描述</div><label class="full">中文描述<textarea name="description_zh" rows="4" placeholder="车辆车况、配置、保养记录等"></textarea></label><label class="full">英文描述<textarea name="description_en" rows="4" placeholder="Vehicle condition, features and service history"></textarea></label><div class="vehicle-photo-manager full" data-photo-manager></div>${editing?'':'<label class="full">或填写图片链接<input name="image" type="url" maxlength="2048" placeholder="https://example.com/car.jpg"></label>'}<label class="featured-check full"><input type="checkbox" name="featured" value="true"> 首页推荐</label><div class="editor-actions full"><button class="btn primary" type="submit">${editing?'保存修改':'保存车辆'}</button><button class="btn" type="button" data-cancel-vehicle-edit>取消</button><span class="muted" id="vehicleSaveResult" role="status"></span></div>`}
function prepareVehicleEditor(form,vehicle=null){cleanupVehiclePhotoManager(form);form.classList.add('vehicle-editor');form.dataset.i18n='1';if(vehicle)form.dataset.editId=String(vehicle.id);else delete form.dataset.editId;form.innerHTML=vehicleEditorMarkup(!!vehicle);if(vehicle){for(const key of ['title','title_zh','title_en','brand','model','bodyType','year','mileage','mileageUnit','price','currency','transmission','displacement','fuelType','driveType','steering','condition','location','description_zh','description_en','status','contact_id'])if(form.elements[key])form.elements[key].value=vehicle[key]??form.elements[key].value;if(!vehicle.title_zh&&!vehicle.title_en)form.elements.title_zh.value=vehicle.title||'';if(!vehicle.description_zh&&!vehicle.description_en)form.elements.description_zh.value=vehicle.description||'';form.elements.featured.checked=!!vehicle.featured}upgradeVehicleBrandField(form,vehicle?.brand||'');upgradePhevFuelField(form);setupVehiclePhotoManager(form,vehicle?vehicleImageList(vehicle):[]);form.onsubmit=saveVehicleEditor;return form}
async function saveVehicleEditor(event){
  event.preventDefault();
  const form=event.currentTarget||event.target;
  if(form.dataset.saving==='1'||form.dataset.saveNeedsReload==='1'||!validatePhotos(form))return;
  const titleZh=form.elements.title_zh.value.trim(),titleEn=form.elements.title_en.value.trim(),result=form.querySelector('#vehicleSaveResult'),button=form.querySelector('button[type="submit"]'),id=form.dataset.editId;
  if(!titleZh&&!titleEn){result.textContent='请至少填写中文标题或英文标题';form.elements.title_zh.focus();return}
  const body=vehicleEditorFormData(form),order=JSON.parse(body.get('photo_order')||'[]');
  body.set('title',titleEn||titleZh);
  form.dataset.saving='1';button.disabled=true;button.textContent='正在保存…';result.textContent='正在保存车辆资料和照片';
  let savedId='';
  try{
    const response=await api(id?'/api/vehicles/'+encodeURIComponent(id):'/api/vehicles',{method:id?'PUT':'POST',body});
    if(response.error||(id&&!response.ok)){result.textContent=response.error||'车辆保存失败，请重试';return}
    savedId=String(id||response.id||'');
    if(!savedId)throw new Error('服务器未返回车辆编号，请刷新核对');
    form.dataset.editId=savedId;
    const saved=await api('/api/vehicles/'+encodeURIComponent(savedId));
    if(saved.error)throw new Error(saved.error);
    const orderSaved=vehiclePhotoOrderMatches(saved,order);
    if(!orderSaved){form.dataset.saveNeedsReload='1';result.textContent='车辆资料已提交，但图片排序未正确保存。请同步更新服务器的 server.js 和 lib/vehicle-photos.js，重启 Node 项目后强制刷新。请关闭此窗口后重新编辑，勿重复上传照片。';return}
    vehicles=await api('/api/vehicles');
    cleanupVehiclePhotoManager(form);$('#adminPanel').innerHTML=vehiclePanel();bindPanel();applyLanguage('zh');
  }catch(error){
    if(savedId){form.dataset.saveNeedsReload='1';result.textContent='车辆资料已提交，但读取保存结果失败。请关闭此窗口，刷新页面后重新编辑核对，勿重复上传照片。'+(error.message||'')}
    else result.textContent='保存失败：'+(error.message||'网络错误，请重试');
  }finally{
    delete form.dataset.saving;
    if(button.isConnected){button.disabled=form.dataset.saveNeedsReload==='1';button.textContent=button.disabled?'请关闭窗口后刷新核对':(form.dataset.editId?'保存修改':'保存车辆')}
  }
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-edit-v]');if(!button)return;const vehicle=vehicles.find(item=>item.id===Number(button.dataset.editV));if(!vehicle)return;$('#addVehicle')?.click();const form=$('#vf');if(form)openVehicleEditorDialog(prepareVehicleEditor(form,vehicle))});
document.addEventListener('click',e=>{if(!e.target.closest('[data-cancel-vehicle-edit]'))return;const form=e.target.closest('form');cleanupVehiclePhotoManager(form);const dialog=form?.closest('dialog');if(dialog){dialog.close();dialog.remove()}else $('#vehicleForm').innerHTML=''});
function addDisplacementField(form,value=''){if(!form||form.elements.displacement)return;const label=document.createElement('label');label.textContent='排量';const input=document.createElement('input');input.name='displacement';input.placeholder='例如 1.5L / 2.0T / 1498cc';input.maxLength=40;input.value=String(value||'');label.appendChild(input);const transmission=form.elements.transmission,anchor=transmission?.closest('label')||transmission;if(anchor)anchor.after(label);else{const fuel=form.elements.fuelType?.closest('label')||form.elements.fuelType;if(fuel)fuel.before(label);else form.appendChild(label)}}
document.addEventListener('click',e=>{if(!e.target.closest('#addVehicle')&&!e.target.closest('[data-edit-v]'))return;setTimeout(()=>{const form=$('#vf');const id=form?.dataset.editId;const vehicle=id?vehicles.find(v=>v.id===Number(id)):null;upgradeVehicleBrandField(form,vehicle?.brand||'');addDisplacementField(form,vehicle?.displacement||'')},0)});
function openNewVehicleEditor(form){if(!form||form.dataset.editId||form.closest('dialog'))return;openVehicleEditorDialog(prepareVehicleEditor(form),'添加车辆资料')}
document.addEventListener('click',e=>{if(!e.target.closest('#addVehicle'))return;setTimeout(()=>openNewVehicleEditor($('#vf')),0)});
document.addEventListener('click',e=>{if(!e.target.closest('#addVehicle'))return;setTimeout(()=>upgradeVehicleBrandField($('#vf'),''),20)});
document.addEventListener('click',e=>{if(!e.target.closest('#addVehicle,[data-edit-v]'))return;setTimeout(()=>upgradePhevFuelField($('#vf')),10)});
document.addEventListener('click',e=>{const b=e.target.closest('[data-edit-c]');if(!b)return;const c=contacts.find(x=>x.id===Number(b.dataset.editC));$('#addContact')?.click();const form=$('#cf');if(!form||!c)return;for(const key of ['name','role','phone','whatsapp','email'])if(form.elements[key])form.elements[key].value=c[key]||'';form.dataset.editId=c.id;form.querySelector('button').textContent='保存修改'});
document.addEventListener('submit',async e=>{const form=e.target;if(form.id!=='cf'||!form.dataset.editId)return;e.preventDefault();const r=await api('/api/contacts/'+form.dataset.editId,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))});if(r.ok){contacts=await api('/api/contacts');$('#adminPanel').innerHTML=contactPanel();bindPanel();applyLanguage('zh')}} ,true);
